package fuzzer

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestValueFuzz(t *testing.T) {
	var obj1, obj2 struct {
		A string
		B int
		C bool
		D float64
	}
	obj1.A = "hello"
	obj1.B = 1
	obj1.C = true
	obj1.D = 1.0

	obj2.A = "hello"
	obj2.B = 1
	obj2.C = true
	obj2.D = 1.0

	obj1 = ValueFuzz(obj1)
	obj2 = ValueFuzz(obj2)

	assert.Equal(t, obj1, obj2)
}

func TestValueFuzzPointer(t *testing.T) {
	var obj1, obj2 *struct {
		A string
		B int
		C bool
		D float64
	}
	obj1 = &obj1
	obj1.A = "hello"
	obj1.B = 1
	obj1.C = true
	obj1.D = 1.0

	obj2 = &obj2
	obj2.A = "hello"
	obj2.B = 1
	obj2.C = true
	obj2.D = 1.0

	obj1 = ValueFuzz(obj1)
	obj2 = ValueFuzz(obj2)

	assert.Equal(t, obj1, obj2)
}

func TestValueFuzzInterface(t *testing.T) {
	var obj1, obj2 interface{}
	obj1 = &struct {
		A string
		B int
		C bool
		D float64
	}{A: "hello", B: 1, C: true, D: 1.0}
	obj2 = &struct {
		A string
		B int
		C bool
		D float64
	}{A: "hello", B: 1, C: true, D: 1.0}

	obj1 = ValueFuzz(obj1)
	obj2 = ValueFuzz(obj2)

	assert.Equal(t, obj1, obj2)
}

